<?php/*Plugin Name: Транслитерируй это! [translit it!]Plugin URI: Description: Осторожно, это БЕТА версия! Переводим или транслитерализируем адреса страниц.Author: Ichi-nyaAuthor URI: http://profiles.wordpress.org/ichi-nyaVersion: 0.1 Beta*/ $talk = array(   "№"=>"#","є"=>"eh",   "а"=>"a","б"=>"b","в"=>"v","г"=>"g","д"=>"d",   "е"=>"e","ё"=>"e","ж"=>"j",   "з"=>"z","и"=>"i","й"=>"y","к"=>"k","л"=>"l",   "м"=>"m","н"=>"n","о"=>"o","п"=>"p","р"=>"r",   "с"=>"s","т"=>"t","у"=>"u","ф"=>"f","х"=>"h",   "ц"=>"c","ч"=>"ch","ш"=>"sh","щ"=>"sch","ъ"=>"",   "ы"=>"y","ь"=>"","э"=>"e","ю"=>"yu","я"=>"ya",   "—"=>"-","«"=>"","»"=>"","…"=>"","№"=>"#"  );$iso = array(   "а"=>"a","б"=>"b","в"=>"v","г"=>"g","д"=>"d",   "е"=>"e","ё"=>"yo","ж"=>"zh",   "з"=>"z","и"=>"i","й"=>"j","к"=>"k","л"=>"l",   "м"=>"m","н"=>"n","о"=>"o","п"=>"p","р"=>"r",   "с"=>"s","т"=>"t","у"=>"u","ф"=>"f","х"=>"x",   "ц"=>"c","ч"=>"ch","ш"=>"sh","щ"=>"shh","ъ"=>"",   "ы"=>"y","ь"=>"","э"=>"e","ю"=>"yu","я"=>"ya",   "—"=>"-","«"=>"","»"=>"","…"=>"","№"=>"#"  );  $try_translate = false;/* 	Обрабатываем выбор*/function sanitize_title_with_translit($title) {	global $talk, $iso;	$rtl_standard = get_option('rtl_standard');	switch ($rtl_standard) {		case 'talk': return strtr(strtolower($title), $talk); break;		case 'iso': return strtr(strtolower($title), $iso); break;		case 'google': return google_sanitize_title($title); break;		case 'yandex': return yandex_sanitize_title($title); break;		default: return $title; break;	}}function google_sanitize_title($title){	global $talk, $try_translate;   /* $rtl_standard = get_option('rtl_standard');    $url = 'http://ajax.googleapis.com/ajax/services/language/translate?v=1.0&q='. urlencode($title) .'&langpair=ru%7Cen';    $translate = file_get_contents($url);    $json = json_decode($translate, true);	if (isset($_POST['rtl_standard'])) {$rtl_standard=true;};    if ($json['responseStatus'] != 200)        return $title;		elseif ($rtl_translate and not($try_translate))		   {$try_translate = true; yandex_sanitize_title($title) ;}		else sanitize_title_with_translit_again($title);    $result = $json['responseData']['translatedText'];     $result = htmlspecialchars_decode($result);    $result = stripslashes($result);    $result = preg_replace("~\W~", '-', $result);    $result = preg_replace('~-+~', '-', $result);    $result = trim($result, '-');	$result = strtolower($result);	*/	// Заглушка	if ($try_translate)		{$result = strtr(strtolower($title), $talk);}		else 		{$try_translate = true; yandex_sanitize_title($title) ;}      return $result;}function yandex_sanitize_title($title){	global $talk, $try_translate;	$rtl_standard = get_option('rtl_standard');	$rtl_translate = get_option('rtl_translate');	$url = 'http://translate.yandex.net/api/v1/tr.json/translate?lang=ru-en&text='. urlencode($title);	$translate = file_get_contents($url);    $json = json_decode($translate, true);	// Проверяем на ошибки получения ответа	if ($json['code'] = !200){		//При ошибке пытаемся перевести через гугл		if ($try_translate)			//Запоминаем, что пытались перевести через Яндекс			{$result = strtr(strtolower($title), $talk);}		else {$try_translate = true; google_sanitize_title($title) ;}  	}	else	// Выбираем результат перевода	$result = $json['text']['0'];	if ($rtl_translate) { 	$result = strtr(strtolower($result), $talk); }    return $result;}function rtl_options_page() {?><div class="wrap">	<h2>Настройки Плагина</h2>	<p>Вы можете выбрать способ, по которому будет производиться транслитерация заголовков.</p>	<?php	if($_POST['rtl_standard']) {		// set the post formatting options		update_option('rtl_standard', $_POST['rtl_standard']);		update_option('rtl_translate', $_POST['rtl_translate']);		echo '<div class="updated"><p>Настройки обновлены.</p></div>';	}	?>	<form method="post">	<fieldset class="options">		<p>Транслитерация происходит только в новых постах</p>		<legend>Производить транслитерацию способом:</legend>		<?php		$rtl_standard = get_option('rtl_standard');		$rtl_translate = get_option('rtl_translate');		?>			<!-- Choice of the method of transliteration -->			<select name="rtl_standard">				<option value="google"<?php if($rtl_standard == 'google'){ echo(' selected="selected"');}?>>Google Translate (non work)</option>				<option value="yandex"<?php if($rtl_standard == 'yandex'){ echo(' selected="selected"');}?>>Yandex Translate</option>				<option value="talk"<?php if($rtl_standard == 'talk'){ echo(' selected="selected"');}?>>Разговорный</option>				<option value="iso"<?php if($rtl_standard == 'iso'){ echo(' selected="selected"');}?>>ISO 9-95</option>				<option value="off"<?php if($rtl_standard == 'off' OR $rtl_standard == ''){ echo(' selected="selected"');}?>>Отключена</option>			</select>			<br />			<p><input type="checkbox" name="rtl_translate" <?php if ($rtl_translate) {echo 'checked="checked"';} ?>value='1' />Производить транслитерацию после переводчика</p>			<input type="submit" value="Изменить" />			<?php if($rtl_standard == 'google') {echo 'Гугл не работает';};?>	</fieldset>	</form></div><?php}// Добавляем опции настроекfunction rtl_add_menu() {		add_options_page('Транслитерируй это!', 'Транслитерируй это!', 8, __FILE__, 'rtl_options_page');}add_action('admin_menu', 'rtl_add_menu');//add_action('sanitize_title', 'sanitize_title_with_translit', 0);// Меняем названия только вручнуюif ( !empty($_POST) || !empty($_GET['action']) && $_GET['action'] == 'edit' || defined('XMLRPC_REQUEST') && XMLRPC_REQUEST ) {	add_action('sanitize_title', 'sanitize_title_with_translit', 0);	}?>